function DeleteConfirmModal({ isOpen, imageName, imageSize, onConfirm, onCancel }) {
  const overlay = document.getElementById('delete-modal-overlay');
  const dialog = document.getElementById('delete-modal-dialog');

  if (isOpen) {
    overlay.classList.add('is-open');
    overlay.setAttribute('aria-hidden', 'false');
    dialog.setAttribute('aria-modal', 'true');
    // Return focus trap baseline
    setTimeout(() => {
      document.getElementById('btn-cancel').focus();
    }, 50);
  } else {
    overlay.classList.remove('is-open');
    overlay.setAttribute('aria-hidden', 'true');
    dialog.setAttribute('aria-modal', 'false');
  }
}

// ── App state ────────────────────────────────────────────────

const state = {
  modalOpen: false,
  deleted: false,
};

function openModal() {
  state.modalOpen = true;
  DeleteConfirmModal({ isOpen: true });
  document.body.style.overflow = 'hidden';
}

function closeModal() {
  state.modalOpen = false;
  DeleteConfirmModal({ isOpen: false });
  document.body.style.overflow = '';
  // Return focus to trigger
  document.querySelector('.trigger').focus();
}

function handleDelete() {
  closeModal();

  const card = document.getElementById('preview-card');
  card.style.transition = 'opacity 0.4s ease, transform 0.4s ease';
  card.style.opacity = '0';
  card.style.transform = 'scale(0.97)';

  setTimeout(() => {
    card.innerHTML = `
      <div style="
        grid-column: 1 / -1;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 16px;
        min-height: 320px;
        color: #8b90a8;
        font-size: 0.9rem;
      ">
        <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24"
          fill="none" stroke="#e84057" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
          <polyline points="20 6 9 17 4 12"/>
        </svg>
        <p style="color: #e8eaf2; font-weight: 600; font-size: 1rem;">Image deleted</p>
        <p>The image has been removed from your library.</p>
      </div>`;
    card.style.opacity = '1';
    card.style.transform = 'scale(1)';
  }, 420);
}

// ── Event wiring ─────────────────────────────────────────────

document.addEventListener('DOMContentLoaded', () => {
  // Open trigger (delete button)
  document.querySelector('.trigger').addEventListener('click', openModal);

  // Cancel / close buttons
  document.getElementById('btn-cancel').addEventListener('click', closeModal);
  document.getElementById('btn-modal-close').addEventListener('click', closeModal);

  // Confirm delete
  document.getElementById('btn-confirm-delete').addEventListener('click', handleDelete);

  // Click outside dialog closes modal
  document.getElementById('delete-modal-overlay').addEventListener('click', (e) => {
    if (e.target === e.currentTarget) closeModal();
  });

  // Escape key closes modal
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && state.modalOpen) closeModal();
  });

  // Focus trap within dialog
  document.getElementById('delete-modal-dialog').addEventListener('keydown', (e) => {
    if (e.key !== 'Tab') return;
    const focusable = Array.from(
      e.currentTarget.querySelectorAll('button, [href], input, [tabindex]:not([tabindex="-1"])')
    ).filter(el => !el.disabled);
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (e.shiftKey) {
      if (document.activeElement === first) { e.preventDefault(); last.focus(); }
    } else {
      if (document.activeElement === last) { e.preventDefault(); first.focus(); }
    }
  });
});
