  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

.modal-image-preview {
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.modal-image-thumb {
  width: 40px;
  height: 40px;
  border-radius: 6px;
  object-fit: cover;
  flex-shrink: 0;
  border: 1px solid var(--border);
}

.modal-image-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  overflow: hidden;
}

.modal-image-name {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.modal-image-size {
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.modal-warning {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  background: rgba(232, 64, 87, 0.07);
  border: 1px solid rgba(232, 64, 87, 0.2);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  font-size: 0.8rem;
  color: #e8a0a8;
  line-height: 1.5;
}

.modal-warning svg {
  flex-shrink: 0;
  width: 14px;
  height: 14px;
  margin-top: 2px;
  color: var(--accent-red);
}

.modal-footer {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}

.modal-footer .btn {
  min-width: 100px;
}

/* ── Close button ──────────────────────────────────────────── */
.modal-close {
  position: absolute;
  top: 16px;
  right: 16px;
  background: transparent;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  cursor: pointer;
  padding: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}
.modal-close:hover {
  background: var(--bg-elevated);
  border-color: var(--border);
  color: var(--text-primary);
}
.modal-close svg {
  width: 18px;
  height: 18px;
}

/* ── Responsive ────────────────────────────────────────────── */
@media (max-width: 680px) {
